inline const char* ReanimTrackIdName(const ReanimTrackId theId)
{
    const std::uint32_t index = static_cast<std::uint32_t>(theId);
    return index >= 1 && index <= PVZ_REANIM_TRACK_ID_COUNT
        ? gReanimTrackIdNames[index - 1].mDisplayName : "<none>";
}

inline bool ReanimTrackIdFromName(const char* const theName, ReanimTrackId& theId)
{
    int low = 0, high = static_cast<int>(PVZ_REANIM_TRACK_ID_COUNT) - 1;
    while (low <= high) {
        const int mid = (low + high) / 2;
        const int cmp = _stricmp(theName, gReanimTrackIdNames[mid].mFoldedName);
        if (cmp == 0) { theId = gReanimTrackIdNames[mid].mId; return true; }
        if (cmp > 0) low = mid + 1; else high = mid - 1;
    }
    return false;
}

struct ReanimTrackIdRange final
{
    ReanimTrackId mLo = ReanimTrackId::None;  // 首个命中（含）
    ReanimTrackId mHi = ReanimTrackId::None;  // 末个命中的下一个（不含）
    [[nodiscard]] constexpr bool Contains(const ReanimTrackId theId) const
    {
        return static_cast<std::uint32_t>(theId) >= static_cast<std::uint32_t>(mLo) &&
            static_cast<std::uint32_t>(theId) < static_cast<std::uint32_t>(mHi);
    }
};

